<div class="orth-section-intro"><div><h3>Historial del expediente</h3><p>Accesos y modificaciones con fecha, autor y contexto clínico.</p></div><span class="orth-status"><?= count($history) ?> eventos</span></div>
<section class="panel"><div class="table-wrap" tabindex="0" role="region" aria-label="Auditoría del expediente"><table><thead><tr><th>Fecha y hora</th><th>Evento</th><th>Autor</th><th>Detalle</th></tr></thead><tbody><?php foreach($history as $event): ?><tr><td><?= local_date($event['created_at'] ?? null) ?></td><td><?= e($event['title'] ?? $event['label'] ?? $eventNames[$event['event_type'] ?? ''] ?? str_replace('_',' ',$event['event_type'] ?? action_label($event['action'] ?? ''))) ?></td><td><?= e($event['author'] ?? $event['user_name'] ?? 'Sistema') ?></td><td class="orth-history-detail"><?= nl2br(e($event['detail'] ?? $event['description'] ?? trim((!empty($event['from_value']) ? $orthoLabel($event['from_value'],$stateNames).' → '.$orthoLabel($event['to_value'] ?? '',$stateNames).'. ':'').($event['reason'] ?? '')))) ?></td></tr><?php endforeach; if(!$history): ?><tr><td colspan="4"><?php $orthoEmpty('Aún no hay eventos disponibles','Las acciones relevantes del expediente se registran de forma auditada.','clock'); ?></td></tr><?php endif; ?></tbody></table></div></section>
